export enum VectorStyle {
  MINIMALIST = "Minimalist Flat Design",
  GEOMETRIC = "Geometric Shapes",
  LINE_ART = "Continuous Line Art",
  LOW_POLY = "Low Poly",
  PIXEL_ART = "Pixel Art Style (SVG Rects)",
  ABSTRACT = "Abstract Artistic",
  WIREFRAME = "Technical Wireframe",
  POP_ART = "Pop Art"
}

export interface VectorGenerationResult {
  svgContent: string;
  originalImage: string; // Base64
  style: VectorStyle;
  timestamp: number;
}

export interface AppState {
  currentImage: string | null;
  isGenerating: boolean;
  result: VectorGenerationResult | null;
  error: string | null;
  history: VectorGenerationResult[];
}

import { GoogleGenAI } from "@google/genai";
import { VectorStyle } from "../types";

const cleanSvgOutput = (text: string): string => {
  // Remove markdown code blocks if present
  let cleaned = text.replace(/```svg/g, '').replace(/```/g, '').trim();

  // Find the start and end of the SVG tag to ensure we only get the code
  const startIndex = cleaned.indexOf('<svg');
  const endIndex = cleaned.lastIndexOf('</svg>');

  if (startIndex !== -1 && endIndex !== -1) {
    cleaned = cleaned.substring(startIndex, endIndex + 6);
  }

  return cleaned;
};

export const generateVectorFromImage = async (
  base64Image: string,
  style: VectorStyle
): Promise<string> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Clean the base64 string if it has the data prefix
  const base64Data = base64Image.split(',')[1] || base64Image;

  const prompt = `
    You are an expert SVG artist and vectorizer.
    Analyze the provided image and recreate it as a clean, efficient, and scalable SVG (Scalable Vector Graphics) code.

    Target Style: ${style}

    Requirements:
    1. Output ONLY the raw SVG code. Do not include markdown formatting or explanations.
    2. Ensure the SVG is self-contained (no external <image> tags with base64 data). It must be drawn using paths, rects, circles, etc.
    3. Keep the complexity reasonable (under 4KB of text if possible) but visually representative.
    4. Use the original image's dominant colors.
    5. The SVG must be valid and renderable in a browser.
    6. Ensure the viewBox matches the aspect ratio of the implied subject.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg', // Assuming JPEG/PNG, the API is flexible with this mime type usually
              data: base64Data
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No output received from Gemini.");
    }

    return cleanSvgOutput(text);

  } catch (error) {
    console.error("Gemini Vectorization Error:", error);
    throw error;
  }
};

import React from 'react';
import { Loader2 } from 'lucide-react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading = false, 
  icon,
  className = '',
  disabled,
  ...props 
}) => {

  const baseStyles = "inline-flex items-center justify-center px-4 py-2 rounded-lg font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-indigo-600 hover:bg-indigo-700 text-white focus:ring-indigo-500 shadow-lg shadow-indigo-500/20",
    secondary: "bg-slate-700 hover:bg-slate-600 text-white focus:ring-slate-500",
    outline: "border border-slate-600 text-slate-300 hover:border-slate-500 hover:text-white bg-transparent",
    ghost: "text-slate-400 hover:text-white hover:bg-slate-800/50"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <Loader2 className="w-5 h-5 mr-2 animate-spin" />
      ) : icon ? (
        <span className="mr-2">{icon}</span>
      ) : null}
      {children}
    </button>
  );
};

import React, { useCallback, useState } from 'react';
import { Upload, Image as ImageIcon, X } from 'lucide-react';

interface ImageUploaderProps {
  currentImage: string | null;
  onImageSelected: (base64: string) => void;
  onClear: () => void;
}

export const ImageUploader: React.FC<ImageUploaderProps> = ({ currentImage, onImageSelected, onClear }) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  }, []);

  const processFile = (file: File) => {
    if (!file.type.startsWith('image/')) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result && typeof event.target.result === 'string') {
        onImageSelected(event.target.result);
      }
    };
    reader.readAsDataURL(file);
  };

  if (currentImage) {
    return (
      <div className="relative group rounded-xl overflow-hidden border border-slate-700 bg-slate-800/50 shadow-xl">
        <img 
          src={currentImage} 
          alt="Source" 
          className="w-full h-64 object-contain bg-slate-900/50"
        />
        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
          <button 
            onClick={onClear}
            className="p-2 bg-red-500/80 hover:bg-red-600 text-white rounded-full transform hover:scale-110 transition-all"
          >
            <X size={24} />
          </button>
        </div>
        <div className="absolute top-2 left-2 bg-black/60 px-2 py-1 rounded text-xs font-mono text-slate-300 backdrop-blur-sm">
          Original Raster
        </div>
      </div>
    );
  }

  return (
    <div
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`
        relative h-64 border-2 border-dashed rounded-xl flex flex-col items-center justify-center text-center p-6 transition-all duration-300
        ${isDragging 
          ? 'border-indigo-500 bg-indigo-500/10 scale-[1.02]' 
          : 'border-slate-700 bg-slate-800/30 hover:border-slate-600 hover:bg-slate-800/50'
        }
      `}
    >
      <input
        type="file"
        accept="image/*"
        onChange={handleFileInput}
        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
      />
      <div className="w-16 h-16 rounded-full bg-slate-800 flex items-center justify-center mb-4 shadow-inner">
        {isDragging ? (
          <Upload className="w-8 h-8 text-indigo-400 animate-bounce" />
        ) : (
          <ImageIcon className="w-8 h-8 text-slate-500" />
        )}
      </div>
      <h3 className="text-lg font-medium text-slate-200 mb-2">
        {isDragging ? 'Drop image here' : 'Upload Image to Vectorize'}
      </h3>
      <p className="text-sm text-slate-400 max-w-xs">
        Drag and drop or click to browse. Supports JPG, PNG, WebP.
      </p>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { Download, Copy, Check, ZoomIn, ZoomOut, Maximize } from 'lucide-react';

interface SvgPreviewProps {
  svgContent: string;
}

export const SvgPreview: React.FC<SvgPreviewProps> = ({ svgContent }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [copied, setCopied] = useState(false);
  const [scale, setScale] = useState(1);

  const handleDownload = () => {
    const blob = new Blob([svgContent], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `vector-art-${Date.now()}.svg`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(svgContent);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const zoomIn = () => setScale(s => Math.min(s + 0.5, 5));
  const zoomOut = () => setScale(s => Math.max(s - 0.5, 0.5));
  const resetZoom = () => setScale(1);

  // Auto-fit logic could go here, but keeping it simple for now

  return (
    <div className="flex flex-col h-full bg-slate-900 rounded-xl overflow-hidden border border-slate-700 shadow-2xl">
      {/* Toolbar */}
      <div className="flex items-center justify-between px-4 py-3 bg-slate-800 border-b border-slate-700">
        <div className="flex items-center space-x-2">
          <span className="text-sm font-medium text-slate-300">Vector Output</span>
          <div className="px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-300 text-xs border border-indigo-500/30">
             SVG
          </div>
        </div>
        <div className="flex items-center space-x-1">
          <button onClick={zoomOut} className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-700 rounded transition-colors" title="Zoom Out">
            <ZoomOut size={16} />
          </button>
           <button onClick={resetZoom} className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-700 rounded transition-colors text-xs font-mono w-12 text-center" title="Reset Zoom">
            {Math.round(scale * 100)}%
          </button>
          <button onClick={zoomIn} className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-700 rounded transition-colors" title="Zoom In">
            <ZoomIn size={16} />
          </button>
          <div className="w-px h-4 bg-slate-700 mx-2" />
          <button 
            onClick={handleCopy} 
            className="p-1.5 text-slate-400 hover:text-indigo-400 hover:bg-slate-700 rounded transition-colors"
            title="Copy Code"
          >
            {copied ? <Check size={16} /> : <Copy size={16} />}
          </button>
          <button 
            onClick={handleDownload}
            className="p-1.5 text-slate-400 hover:text-emerald-400 hover:bg-slate-700 rounded transition-colors"
            title="Download SVG"
          >
            <Download size={16} />
          </button>
        </div>
      </div>

      {/* SVG Container */}
      <div className="flex-1 overflow-hidden relative bg-[url('https://grainy-gradients.vercel.app/noise.svg')] bg-slate-900 flex items-center justify-center p-8">
        {/* Checkerboard background for transparency */}
        <div className="absolute inset-0 opacity-10" 
             style={{ 
               backgroundImage: 'linear-gradient(45deg, #333 25%, transparent 25%), linear-gradient(-45deg, #333 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #333 75%), linear-gradient(-45deg, transparent 75%, #333 75%)',
               backgroundSize: '20px 20px',
               backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px' 
             }} 
        />

        <div 
          ref={containerRef}
          className="relative z-10 transition-transform duration-300 ease-out origin-center shadow-2xl"
          style={{ transform: `scale(${scale})` }}
          dangerouslySetInnerHTML={{ __html: svgContent }}
        />
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
