    if (!currentImage) return;

    setIsGenerating(true);
    setError(null);

    try {
      const svgContent = await generateVectorFromImage(currentImage, selectedStyle);

      const newResult: VectorGenerationResult = {
        svgContent,
        originalImage: currentImage,
        style: selectedStyle,
        timestamp: Date.now()
      };

      setResult(newResult);
      setHistory(prev => [newResult, ...prev]);
    } catch (err: any) {
      setError(err.message || "Failed to generate vector. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const loadFromHistory = (item: VectorGenerationResult) => {
    setResult(item);
    setCurrentImage(item.originalImage);
    setSelectedStyle(item.style);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 selection:bg-indigo-500/30">
