            <section className="space-y-4">
              <div className="flex items-center justify-between">
                <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider">Input Source</h2>
              </div>
              <ImageUploader 
                currentImage={currentImage} 
                onImageSelected={setCurrentImage} 
                onClear={() => {
                  setCurrentImage(null);
                  setResult(null);
                }}
              />
            </section>

            {/* Style Selection */}
            <section className="space-y-4">
              <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider flex items-center">
                <Layers className="w-4 h-4 mr-2" />
                Vector Style
              </h2>
              <div className="grid grid-cols-2 gap-3">
                {Object.values(VectorStyle).map((style) => (
                  <button
                    key={style}
                    onClick={() => setSelectedStyle(style)}
                    className={`
                      px-3 py-3 rounded-lg text-sm text-left transition-all border
                      ${selectedStyle === style 
                        ? 'bg-indigo-600/20 border-indigo-500 text-white shadow-lg shadow-indigo-500/10' 
                        : 'bg-slate-800/50 border-slate-700 text-slate-400 hover:bg-slate-800 hover:border-slate-600'
                      }
                    `}
                  >
                    {style}
