              icon={<Wand2 className="w-5 h-5" />}
            >
              {isGenerating ? 'Vectorizing...' : 'Generate Vector'}
            </Button>

            {error && (
              <div className="p-4 bg-red-900/20 border border-red-800/50 rounded-lg flex items-start space-x-3 text-red-200 text-sm">
                <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
                <p>{error}</p>
              </div>
            )}

            {/* History */}
            {history.length > 0 && (
              <section className="space-y-4 pt-4 border-t border-slate-800">
                <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider flex items-center">
                  <History className="w-4 h-4 mr-2" />
                  Recent
