                <div className="space-y-2">
                  {history.map((item, idx) => (
                    <button
                      key={item.timestamp}
                      onClick={() => loadFromHistory(item)}
                      className="w-full p-2 rounded-lg bg-slate-800/30 hover:bg-slate-800 border border-slate-800 hover:border-slate-700 flex items-center space-x-3 transition-all group"
                    >
                      <div 
                        className="w-10 h-10 rounded bg-slate-900 p-1 overflow-hidden flex-shrink-0"
