                <p className="text-slate-500 max-w-md">
                  Upload an image and select a style to generate a scalable vector graphic using Gemini's vision capabilities.
                </p>
                <div className="mt-8 flex flex-wrap justify-center gap-4 opacity-50">
                  <div className="h-20 w-20 bg-slate-800 rounded animate-pulse delay-75"></div>
                  <div className="h-20 w-20 bg-slate-800 rounded animate-pulse delay-100"></div>
                  <div className="h-20 w-20 bg-slate-800 rounded animate-pulse delay-150"></div>
                </div>
              </div>
            )}
          </div>

        </div>
      </main>
    </div>
  );
};

export default App;

