import { GoogleGenAI } from "@google/genai";
import { VectorStyle } from "../types";

// We use the flash preview model for fast multimodal understanding and code generation
const MODEL_NAME = 'gemini-2.5-flash';

const cleanSvgCode = (text: string): string => {
  // Remove markdown code blocks
  let cleaned = text.replace(/```svg/gi, '').replace(/```xml/gi, '').replace(/```/g, '').trim();

  // Extract just the SVG tag content if there's extra text
  const svgStart = cleaned.indexOf('<svg');
  const svgEnd = cleaned.lastIndexOf('</svg>');

  if (svgStart !== -1 && svgEnd !== -1) {
    cleaned = cleaned.substring(svgStart, svgEnd + 6);
  }

  return cleaned;
};

export const generateVectorSvg = async (
  base64Image: string,
  style: VectorStyle
): Promise<string> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Ensure cleaner base64 without headers for the API if needed, 
  // though the API is generally robust.
  const base64Data = base64Image.includes(',') 
    ? base64Image.split(',')[1] 
    : base64Image;

  const prompt = `
    Role: Expert SVG Artist and Coder.
    Task: Convert the provided image into a clean, scalable SVG (Scalable Vector Graphics) file.

    Target Style: ${style}

    Strict Constraints:
    1. Output ONLY valid SVG code. No markdown, no explanations.
    2. DO NOT use <image> tags with base64 data. You must draw the image using <path>, <rect>, <circle>, <polygon>, etc.
    3. Simplify the details. Do not attempt pixel-perfect photorealism. Create an artistic vector interpretation.
    4. Use a limited, harmonious color palette based on the original image.
    5. Ensure the 'viewBox' matches the aspect ratio of the image.
    6. Code must be efficient and under 8KB if possible.

    For ${style}:
    ${getStyleInstructions(style)}
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg', // Standardize on jpeg for input usually works best
              data: base64Data
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("Gemini returned empty response.");
    }

    const svg = cleanSvgCode(text);

    if (!svg.startsWith('<svg')) {
      throw new Error("Failed to generate valid SVG code.");
    }

    return svg;

  } catch (error) {
    console.error("Vectorization failed:", error);
    throw error;
  }
};

function getStyleInstructions(style: VectorStyle): string {
  switch (style) {
    case VectorStyle.MINIMALIST:
      return "Use large flat areas of color, remove small details, use smooth curves.";
    case VectorStyle.GEOMETRIC:
      return "Construct the image entirely out of geometric primitives (circles, triangles, squares).";
    case VectorStyle.LINE_ART:
      return "Use strokes only (no fill), continuous lines, varying stroke width for depth.";
    case VectorStyle.LOW_POLY:
      return "Use a mesh of triangles with flat colors to create a 3D low-poly effect.";
    case VectorStyle.PIXEL_ART:
      return "Use a grid of <rect> elements to simulate pixel art. Keep resolution low (e.g. 64x64 grid).";
    case VectorStyle.WIREFRAME:
      return "Use thin strokes, transparent fills, and connect key points like a 3D model wireframe.";
    case VectorStyle.STENCIL:
      return "High contrast, 2-3 colors max, distinct separation between light and dark areas.";
    default:
      return "Balance detail with simplicity.";
  }
}

import React, { useState } from 'react';
import { Download, Copy, Check, ZoomIn, ZoomOut, Maximize } from 'lucide-react';

interface SvgPreviewProps {
  svgContent: string;
}

export const SvgPreview: React.FC<SvgPreviewProps> = ({ svgContent }) => {
  const [scale, setScale] = useState(1);
  const [copied, setCopied] = useState(false);

  const handleDownload = () => {
    const blob = new Blob([svgContent], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `vector-art-${Date.now()}.svg`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(svgContent);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 rounded-xl overflow-hidden border border-slate-700 shadow-xl">
      {/* Toolbar */}
      <div className="flex items-center justify-between px-4 py-2 bg-slate-800 border-b border-slate-700">
        <div className="flex items-center gap-2">
          <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Vector Output</span>
          <span className="bg-indigo-500/20 text-indigo-300 text-[10px] px-1.5 py-0.5 rounded border border-indigo-500/30">SVG</span>
        </div>
        <div className="flex items-center gap-1">
          <button onClick={() => setScale(s => Math.max(0.5, s - 0.25))} className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-700 rounded transition-colors" title="Zoom Out">
            <ZoomOut size={16} />
          </button>
          <span className="text-xs font-mono text-slate-500 w-12 text-center">{Math.round(scale * 100)}%</span>
          <button onClick={() => setScale(s => Math.min(4, s + 0.25))} className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-700 rounded transition-colors" title="Zoom In">
            <ZoomIn size={16} />
          </button>
          <div className="w-px h-4 bg-slate-700 mx-2" />
          <button onClick={handleCopy} className="p-1.5 text-slate-400 hover:text-indigo-400 hover:bg-slate-700 rounded transition-colors" title="Copy Code">
            {copied ? <Check size={16} /> : <Copy size={16} />}
          </button>
          <button onClick={handleDownload} className="p-1.5 text-slate-400 hover:text-emerald-400 hover:bg-slate-700 rounded transition-colors" title="Download SVG">
            <Download size={16} />
          </button>
        </div>
      </div>

      {/* Preview Area */}
      <div className="flex-1 overflow-auto relative bg-[url('https://grainy-gradients.vercel.app/noise.svg')] bg-slate-950 flex items-center justify-center p-8">
        <div 
          className="absolute inset-0 opacity-10 pointer-events-none"
          style={{ 
            backgroundImage: 'linear-gradient(45deg, #333 25%, transparent 25%), linear-gradient(-45deg, #333 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #333 75%), linear-gradient(-45deg, transparent 75%, #333 75%)',
            backgroundSize: '20px 20px',
            backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px' 
          }} 
        />

        <div 
          className="relative z-10 transition-transform duration-200 ease-out shadow-2xl origin-center bg-transparent"
          style={{ transform: `scale(${scale})` }}
          dangerouslySetInnerHTML={{ __html: svgContent }}
        />
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ImageDropzone } from './components/ImageDropzone';
import { SvgPreview } from './components/SvgPreview';
import { generateVectorSvg } from './services/geminiService';
import { VectorStyle, VectorResult } from './types';
import { Wand2, Layers, AlertCircle, Sparkles } from 'lucide-react';

function App() {
  const [currentImage, setCurrentImage] = useState<string | null>(null);
  const [selectedStyle, setSelectedStyle] = useState<VectorStyle>(VectorStyle.MINIMALIST);
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<VectorResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleImageSelected = (base64: string) => {
    setCurrentImage(base64);
    setResult(null);
    setError(null);
  };

  const handleGenerate = async () => {
    if (!currentImage) return;

    setIsGenerating(true);
    setError(null);

    try {
      const svgCode = await generateVectorSvg(currentImage, selectedStyle);

      setResult({
        svg: svgCode,
        original: currentImage,
        style: selectedStyle,
        timestamp: Date.now()
      });
    } catch (err: any) {
      setError(err.message || "Failed to vectorize image. Try a different image or style.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-indigo-500/30">

      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Sparkles className="text-white w-5 h-5" />
            </div>
            <h1 className="text-lg font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
              AI Vectorizer Studio
            </h1>
          </div>
          <div className="text-xs font-mono text-slate-500 px-3 py-1 bg-slate-900 rounded-full border border-slate-800">
            Gemini 2.5 Flash
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 lg:p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 h-[calc(100vh-4rem)]">

        {/* Left Panel: Inputs */}
        <div className="lg:col-span-4 flex flex-col gap-6 overflow-y-auto pb-8 custom-scrollbar">

          {/* Upload Section */}
          <section className="space-y-3">
            <h2 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Input Source</h2>
            {currentImage ? (
              <div className="relative group rounded-xl overflow-hidden border border-slate-700 bg-slate-900 shadow-xl">
                <img 
                  src={currentImage} 
                  alt="Source" 
                  className="w-full h-48 object-contain bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-90" 
                />
                <button 
                  onClick={() => {
                    setCurrentImage(null);
                    setResult(null);
                  }}
                  className="absolute top-2 right-2 p-1.5 bg-slate-900/80 hover:bg-red-500 text-white rounded-lg backdrop-blur-sm transition-colors border border-slate-700"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
                </button>
              </div>
            ) : (
              <ImageDropzone onImageSelected={handleImageSelected} />
            )}
          </section>

          {/* Style Selector */}
          <section className="space-y-3">
            <div className="flex items-center gap-2 text-xs font-bold text-slate-500 uppercase tracking-wider">
              <Layers size={14} />
              <span>Vector Style</span>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              {Object.values(VectorStyle).map((style) => (
                <button
                  key={style}
                  onClick={() => setSelectedStyle(style)}
                  disabled={isGenerating}
                  className={`
                    px-3 py-3 rounded-lg text-sm text-left transition-all border relative overflow-hidden group
                    ${selectedStyle === style 
                      ? 'bg-indigo-600/10 border-indigo-500 text-indigo-200' 
                      : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700 hover:bg-slate-800'
                    }
                  `}
                >
                  <span className="relative z-10">{style}</span>
                  {selectedStyle === style && (
                    <div className="absolute inset-0 bg-indigo-500/5 z-0" />
                  )}
                </button>
              ))}
            </div>
          </section>

          {/* Generate Button */}
          <button
            onClick={handleGenerate}
            disabled={!currentImage || isGenerating}
            className={`
              w-full py-4 rounded-xl font-semibold text-lg shadow-lg flex items-center justify-center gap-2 transition-all duration-300
              ${!currentImage || isGenerating 
                ? 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700' 
                : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white hover:scale-[1.02] shadow-indigo-500/25 border border-indigo-500/50'
              }
            `}
          >
            {isGenerating ? (
              <>
                <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
                <span>Vectorizing...</span>
              </>
            ) : (
              <>
                <Wand2 size={20} />
                <span>Generate SVG</span>
              </>
            )}
          </button>

          {error && (
            <div className="p-4 bg-red-900/20 border border-red-800/50 rounded-lg flex gap-3 text-red-200 text-sm animate-in fade-in slide-in-from-top-2">
              <AlertCircle className="w-5 h-5 flex-shrink-0 text-red-400" />
              <p>{error}</p>
            </div>
          )}
        </div>

        {/* Right Panel: Output */}
        <div className="lg:col-span-8 flex flex-col h-full min-h-[400px]">
          {result ? (
            <SvgPreview svgContent={result.svg} />
          ) : (
            <div className="flex-1 rounded-xl border-2 border-dashed border-slate-800 bg-slate-900/20 flex flex-col items-center justify-center text-center p-12">
              <div className="w-20 h-20 rounded-2xl bg-slate-900 border border-slate-800 flex items-center justify-center mb-6 shadow-2xl">
                <Wand2 className="w-8 h-8 text-slate-600" />
              </div>
              <h3 className="text-xl font-medium text-slate-300 mb-2">Ready to Vectorize</h3>
              <p className="text-slate-500 max-w-sm mx-auto leading-relaxed">
                Upload a raster image to convert it into clean, scalable SVG paths using Gemini's vision capabilities.
              </p>

              <div className="mt-12 grid grid-cols-3 gap-4 opacity-30 pointer-events-none">
                 <div className="w-24 h-24 rounded border border-slate-700 bg-slate-800/50"></div>
                 <div className="w-24 h-24 rounded border border-slate-700 bg-slate-800/50"></div>
                 <div className="w-24 h-24 rounded border border-slate-700 bg-slate-800/50"></div>
              </div>
            </div>
          )}
        </div>

      </main>
    </div>
  );
}

export default App;
